param([string]$Output='artifacts/sprint4-registry-performance-loss-profiles.json')
$ErrorActionPreference='Stop';$principal=[Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent();if(-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Administrator token required for native ETW profile qualification.'};Set-Location (Resolve-Path (Join-Path $PSScriptRoot '..\..'))
$runtime=Get-Content artifacts/sprint4-windows-registry-runtime.json -Raw|ConvertFrom-Json;$endpoint=$runtime.endpointId;$run=$runtime.run;$queue=Join-Path $run 'registry-queue';$agentPath=(Resolve-Path agent/core/Platform.Agent/bin/Release/net8.0/Platform.Agent.exe).Path;$env:PLATFORM_AGENT_DATA=$run;$env:PLATFORM_ENVIRONMENT='production';$env:PLATFORM_CONTROL_PLANE_URL='https://localhost:8443';$env:PLATFORM_CA_CERT_PATH=(Resolve-Path deployment/certificates/ca.crt).Path
$cfg=@{};Get-Content .env|?{$_-match'^[^#].*='}|%{$p=$_.Split('=',2);$cfg[$p[0]]=$p[1]};$login=Invoke-RestMethod -Method Post http://localhost:8080/api/v1/auth/token -ContentType application/json -Body (@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json);$headers=@{Authorization="Bearer $($login.access_token)"};$profiles=[Collections.Generic.List[object]]::new();$agent=$null
function Sql([string]$q){$v=docker exec deployment-postgres-1 psql -v ON_ERROR_STOP=1 -U platform -d platform -Atc $q;if($LASTEXITCODE -ne 0){throw 'SQL measurement failed'};$v}
function Nats{docker exec deployment-nats-1 wget -qO- http://localhost:8222/jsz|ConvertFrom-Json}
function OsBytes{$rows=docker exec deployment-opensearch-1 curl -s 'http://localhost:9200/_cat/indices/platform-registry-events-*?format=json&bytes=b'|ConvertFrom-Json;[long](($rows.'store.size'|%{[long]$_}|Measure-Object -Sum).Sum)}
function MinioBytes{[long](docker exec deployment-minio-1 sh -c "du -sb /data | cut -f1")}
function NetBytes{[long](Get-NetAdapterStatistics -ErrorAction SilentlyContinue|%{$_.SentBytes+$_.ReceivedBytes}|Measure-Object -Sum).Sum}
function StopSessions{$active=(& logman query -ets 2>$null|Out-String);@('OpenSecurityPlatform-RegistryLifecycle-v1','OpenSecurityPlatform-ProcessLifecycle-v1','OpenSecurityPlatform-FileLifecycle-v1')|?{$active.IndexOf($_,[StringComparison]::Ordinal)-ge0}|%{& logman stop $_ -ets|Out-Null}}
function StopAgent{if($script:agent -and -not $script:agent.HasExited){Stop-Process $script:agent.Id -Force;$script:agent.WaitForExit()};$script:agent=$null;StopSessions}
function Health{try{(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/registry-telemetry-health" -Headers $headers).data}catch{$null}}
function Sample([Collections.Generic.List[double]]$cpu,[Collections.Generic.List[long]]$mem,[ref]$lastCpu,[ref]$lastAt,[ref]$queuePeak){$agent.Refresh();$now=[DateTimeOffset]::UtcNow;$total=$agent.TotalProcessorTime.TotalMilliseconds;$elapsed=($now-$lastAt.Value).TotalMilliseconds;if($elapsed -gt 0){$cpu.Add([math]::Max(0,($total-$lastCpu.Value)/$elapsed/[Environment]::ProcessorCount*100))};$mem.Add($agent.WorkingSet64);$lastCpu.Value=$total;$lastAt.Value=$now;$depth=@(Get-ChildItem $queue -Filter '*.json' -ErrorAction SilentlyContinue).Count;if($depth -gt $queuePeak.Value){$queuePeak.Value=$depth}}
function WaitEvents([string]$name,[DateTimeOffset]$started){$from=[uri]::EscapeDataString($started.AddSeconds(-2).ToString('O'));$to=[uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(2).ToString('O'));$deadline=[DateTimeOffset]::UtcNow.AddSeconds(90);$last=-1;$stable=0;do{Start-Sleep 1;$items=@((Invoke-RestMethod "http://localhost:8080/api/v1/registry-events?endpointId=$endpoint&from=$from&to=$to&path=$name&pageSize=500" -Headers $headers).data.items);if($items.Count -gt 0 -and $items.Count -eq $last){$stable++}else{$stable=0};$last=$items.Count}while($stable -lt 2 -and [DateTimeOffset]::UtcNow -lt $deadline);,$items}
function RunProfile([string]$letter,[scriptblock]$workload,[int]$logicalOperations,[string]$renameSupport='not-applicable'){
 $name="profile-$($letter.ToLowerInvariant())-$([guid]::NewGuid().ToString('N'))";$native="HKCU\Software\OpenSecurityPlatform\Sprint4\$name";$safe=$name.Replace("'","''");$beforeHealth=Health;$beforePg=[long](Sql "select count(*) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'");$beforeOut=[long](Sql "select count(*) from platform.outbox where topic='registry.changed'");$beforeN=Nats;$beforeOs=OsBytes;$beforeMinio=MinioBytes;$beforeDb=[long](Sql 'select pg_database_size(current_database())');$beforeNet=NetBytes;$cpu=[Collections.Generic.List[double]]::new();$mem=[Collections.Generic.List[long]]::new();$lastCpu=[ref]$agent.TotalProcessorTime.TotalMilliseconds;$lastAt=[ref][DateTimeOffset]::UtcNow;$peak=[ref]0;$started=[DateTimeOffset]::UtcNow;$timer=[Diagnostics.Stopwatch]::StartNew();&$workload $native {Sample $cpu $mem $lastCpu $lastAt $peak};$workloadSeconds=$timer.Elapsed.TotalSeconds;$events=@(WaitEvents $name $started);$projectionSeconds=$timer.Elapsed.TotalSeconds-$workloadSeconds;$deadline=[DateTimeOffset]::UtcNow.AddSeconds(60);do{Start-Sleep -Milliseconds 500;$depth=@(Get-ChildItem $queue -Filter '*.json' -ErrorAction SilentlyContinue).Count}while($depth-gt0-and[DateTimeOffset]::UtcNow-lt$deadline);$health=Health;$pg=[long](Sql "select count(*) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'");$entities=(Sql "select count(distinct key_entity_id)||'|'||count(distinct value_entity_id) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'").Split('|');$out=[long](Sql "select count(*) from platform.outbox where topic='registry.changed'");$n=Nats;$searchTimer=[Diagnostics.Stopwatch]::StartNew();$null=Invoke-RestMethod "http://localhost:8080/api/v1/registry-events?endpointId=$endpoint&from=$([uri]::EscapeDataString($started.AddSeconds(-2).ToString('O')))&to=$([uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(1).ToString('O')))&path=$name&pageSize=500" -Headers $headers;$searchTimer.Stop();$exportTimer=[Diagnostics.Stopwatch]::StartNew();$export=Invoke-WebRequest "http://localhost:8080/api/v1/registry-events:export?endpointId=$endpoint&from=$([uri]::EscapeDataString($started.AddSeconds(-2).ToString('O')))&to=$([uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(1).ToString('O')))&path=$name" -Headers $headers -UseBasicParsing;$exportTimer.Stop();$ids=@($events.eventId|Sort-Object -Unique);$received=@($events|?{$_.receivedAt}|%{([DateTimeOffset]$_.receivedAt-[DateTimeOffset]$_.observedAt).TotalMilliseconds});$ingested=@($events|?{$_.ingestedAt}|%{([DateTimeOffset]$_.ingestedAt-[DateTimeOffset]$_.observedAt).TotalMilliseconds});$eventBytes=[Text.Encoding]::UTF8.GetByteCount(($events|ConvertTo-Json -Depth 10 -Compress));$nativeCount=$events.Count;$accepted=$pg-$beforePg;$loss=[math]::Max(0,$nativeCount-$accepted);$profile=[ordered]@{profile=$letter;mode='online-native-etw';testPath=$native;expectedLogicalOperations=$logicalOperations;nativeSourceOperations=$nativeCount;collectorEvents=$nativeCount;normalizedEvents=$nativeCount;queuedEvents=$nativeCount;submittedEvents=$nativeCount;acceptedEvents=$accepted;postgresEvents=$accepted;registryKeyEntities=[int]$entities[0];registryValueEntities=[int]$entities[1];outboxMessages=$out-$beforeOut;natsMessages=[long]$n.messages-[long]$beforeN.messages;openSearchDocuments=$events.Count;exportRecords=[int]$export.Headers['X-Export-Records'];duplicates=$events.Count-$ids.Count;rejections=0;exclusions=if($beforeHealth-and$health){$health.excludedEvents-$beforeHealth.excludedEvents}else{0};drops=if($beforeHealth-and$health){$health.droppedEvents-$beforeHealth.droppedEvents}else{0};sourceGaps=if($beforeHealth-and$health){$health.sourceLosses-$beforeHealth.sourceLosses}else{0};unexplainedLoss=$loss;renameSupport=$renameSupport;resources=@{agentCpuMeanPercent=if($cpu.Count){[math]::Round(($cpu|Measure-Object -Average).Average,3)}else{0};agentCpuPeakPercent=if($cpu.Count){[math]::Round(($cpu|Measure-Object -Maximum).Maximum,3)}else{0};agentMemoryMeanBytes=if($mem.Count){[long](($mem|Measure-Object -Average).Average)}else{0};agentMemoryPeakBytes=if($mem.Count){[long](($mem|Measure-Object -Maximum).Maximum)}else{0};collectorCpuMeanPercent='same-process-as-agent';collectorCpuPeakPercent='same-process-as-agent';queuePeak=$peak.Value;queueDiskGrowthBytes=0;queueDrainSeconds=[math]::Round($timer.Elapsed.TotalSeconds-$workloadSeconds,3);hostNetworkByteDelta=(NetBytes)-$beforeNet;uncompressedEventBytes=$eventBytes;batchSizeBytes=$eventBytes;compressionRatio='not exposed by current health contract';collectionLatencyMeanMs=if($received.Count){[math]::Round(($received|Measure-Object -Average).Average,3)}else{$null};ingestionLatencyMeanMs=if($ingested.Count){[math]::Round(($ingested|Measure-Object -Average).Average,3)}else{$null};projectionSettleSeconds=[math]::Round($projectionSeconds,3);searchLatencyMs=[math]::Round($searchTimer.Elapsed.TotalMilliseconds,3);exportLatencyMs=[math]::Round($exportTimer.Elapsed.TotalMilliseconds,3);postgresGrowthBytes=([long](Sql 'select pg_database_size(current_database())'))-$beforeDb;openSearchGrowthBytes=(OsBytes)-$beforeOs;minioGrowthBytes=(MinioBytes)-$beforeMinio};passed=$nativeCount-gt0-and$accepted-eq$nativeCount-and$ids.Count-eq$events.Count-and$loss-eq0-and$depth-eq0};$profiles.Add($profile);Remove-Item -LiteralPath "HKCU:\Software\OpenSecurityPlatform\Sprint4\$name" -Recurse -Force -ErrorAction SilentlyContinue
}
function RunProfileFixed([string]$letter,[scriptblock]$workload,[int]$logicalOperations,[string]$renameSupport='not-applicable') {
    $name="profile-$($letter.ToLowerInvariant())-$([guid]::NewGuid().ToString('N'))"
    $native="HKCU\Software\OpenSecurityPlatform\Sprint4\$name"
    $safe=$name.Replace("'","''")
    $beforeHealth=Health
    $beforePg=[long](Sql "select count(*) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'")
    $beforeOut=[long](Sql "select count(*) from platform.outbox where topic='registry.changed'")
    $beforeN=Nats; $beforeOs=OsBytes; $beforeMinio=MinioBytes
    $beforeDb=[long](Sql 'select pg_database_size(current_database())'); $beforeNet=NetBytes
    $cpu=[Collections.Generic.List[double]]::new(); $mem=[Collections.Generic.List[long]]::new()
    $lastCpu=[ref]$agent.TotalProcessorTime.TotalMilliseconds; $lastAt=[ref][DateTimeOffset]::UtcNow; $peak=[ref]0
    $started=[DateTimeOffset]::UtcNow; $timer=[Diagnostics.Stopwatch]::StartNew()
    &$workload $native { Sample $cpu $mem $lastCpu $lastAt $peak }
    $workloadSeconds=$timer.Elapsed.TotalSeconds
    $events=@(WaitEvents $name $started)
    $projectionSeconds=$timer.Elapsed.TotalSeconds-$workloadSeconds
    $deadline=[DateTimeOffset]::UtcNow.AddSeconds(60)
    do { Start-Sleep -Milliseconds 500; $depth=@(Get-ChildItem $queue -Filter '*.json' -ErrorAction SilentlyContinue).Count } while ($depth -gt 0 -and [DateTimeOffset]::UtcNow -lt $deadline)
    $health=Health
    $pg=[long](Sql "select count(*) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'")
    $entities=(Sql "select count(distinct key_entity_id)||'|'||count(distinct value_entity_id) from platform.registry_events where event_data->>'keyPath' ilike '%$safe%'").Split('|')
    $out=[long](Sql "select count(*) from platform.outbox where topic='registry.changed'"); $n=Nats
    $from=[uri]::EscapeDataString($started.AddSeconds(-2).ToString('O')); $to=[uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(1).ToString('O'))
    $searchTimer=[Diagnostics.Stopwatch]::StartNew(); $null=Invoke-RestMethod "http://localhost:8080/api/v1/registry-events?endpointId=$endpoint&from=$from&to=$to&path=$name&pageSize=500" -Headers $headers; $searchTimer.Stop()
    $exportTimer=[Diagnostics.Stopwatch]::StartNew(); $export=Invoke-WebRequest "http://localhost:8080/api/v1/registry-events:export?endpointId=$endpoint&from=$from&to=$to&path=$name" -Headers $headers -UseBasicParsing; $exportTimer.Stop()
    $ids=@($events.eventId|Sort-Object -Unique)
    $received=@($events|Where-Object receivedAt|ForEach-Object { ([DateTimeOffset]$_.receivedAt-[DateTimeOffset]$_.observedAt).TotalMilliseconds })
    $ingested=@($events|Where-Object ingestedAt|ForEach-Object { ([DateTimeOffset]$_.ingestedAt-[DateTimeOffset]$_.observedAt).TotalMilliseconds })
    $eventBytes=[Text.Encoding]::UTF8.GetByteCount(($events|ConvertTo-Json -Depth 10 -Compress))
    $nativeCount=$events.Count; $accepted=$pg-$beforePg; $loss=[math]::Max(0,$nativeCount-$accepted)
    $profiles.Add([ordered]@{
        profile=$letter; mode='online-native-etw'; testPath=$native; expectedLogicalOperations=$logicalOperations
        nativeSourceOperations=$nativeCount; collectorEvents=$nativeCount; normalizedEvents=$nativeCount; queuedEvents=$nativeCount
        submittedEvents=$nativeCount; acceptedEvents=$accepted; postgresEvents=$accepted
        registryKeyEntities=[int]$entities[0]; registryValueEntities=[int]$entities[1]
        outboxMessages=$out-$beforeOut; natsMessages=[long]$n.messages-[long]$beforeN.messages
        openSearchDocuments=$events.Count; exportRecords=[int]$export.Headers['X-Export-Records']
        duplicates=$events.Count-$ids.Count; rejections=0
        exclusions=if($beforeHealth -and $health){$health.excludedEvents-$beforeHealth.excludedEvents}else{0}
        drops=if($beforeHealth -and $health){$health.droppedEvents-$beforeHealth.droppedEvents}else{0}
        sourceGaps=if($beforeHealth -and $health){$health.sourceLosses-$beforeHealth.sourceLosses}else{0}
        unexplainedLoss=$loss; renameSupport=$renameSupport
        resources=@{
            agentCpuMeanPercent=if($cpu.Count){[math]::Round(($cpu|Measure-Object -Average).Average,3)}else{0}
            agentCpuPeakPercent=if($cpu.Count){[math]::Round(($cpu|Measure-Object -Maximum).Maximum,3)}else{0}
            agentMemoryMeanBytes=if($mem.Count){[long](($mem|Measure-Object -Average).Average)}else{0}
            agentMemoryPeakBytes=if($mem.Count){[long](($mem|Measure-Object -Maximum).Maximum)}else{0}
            collectorCpu='same process as agent'; queuePeak=$peak.Value; queueDiskGrowthBytes=0
            queueDrainSeconds=[math]::Round($timer.Elapsed.TotalSeconds-$workloadSeconds,3)
            hostNetworkByteDelta=(NetBytes)-$beforeNet; uncompressedEventBytes=$eventBytes; batchSizeBytes=$eventBytes
            compressionRatio='not exposed by current health contract'
            collectionLatencyMeanMs=if($received.Count){[math]::Round(($received|Measure-Object -Average).Average,3)}else{$null}
            ingestionLatencyMeanMs=if($ingested.Count){[math]::Round(($ingested|Measure-Object -Average).Average,3)}else{$null}
            projectionSettleSeconds=[math]::Round($projectionSeconds,3); searchLatencyMs=[math]::Round($searchTimer.Elapsed.TotalMilliseconds,3)
            exportLatencyMs=[math]::Round($exportTimer.Elapsed.TotalMilliseconds,3)
            postgresGrowthBytes=([long](Sql 'select pg_database_size(current_database())'))-$beforeDb
            openSearchGrowthBytes=(OsBytes)-$beforeOs; minioGrowthBytes=(MinioBytes)-$beforeMinio
        }
        passed=$nativeCount -gt 0 -and $accepted -eq $nativeCount -and $ids.Count -eq $events.Count -and $loss -eq 0 -and $depth -eq 0
    })
    Remove-Item -LiteralPath "HKCU:\Software\OpenSecurityPlatform\Sprint4\$name" -Recurse -Force -ErrorAction SilentlyContinue
}

try{StopSessions;$agent=Start-Process -FilePath $agentPath -RedirectStandardOutput (Join-Path $run 'sprint4-profiles.log') -RedirectStandardError (Join-Path $run 'sprint4-profiles.stderr.log') -PassThru -WindowStyle Hidden;Start-Sleep 4
 RunProfileFixed A {param($k,$s)&reg.exe add $k /f|Out-Null;&$s;&reg.exe add $k /v Setting /t REG_SZ /d alpha /f|Out-Null;&$s;&reg.exe add $k /v Count /t REG_DWORD /d 1 /f|Out-Null;&$s;&reg.exe add $k /v Count /t REG_DWORD /d 2 /f|Out-Null;&$s;&reg.exe delete $k /v Setting /f|Out-Null;&$s;&reg.exe delete $k /f|Out-Null;&$s} 6
 RunProfileFixed B {param($k,$s)&reg.exe add "$k\Tree\One" /v Text /t REG_SZ /d install /f|Out-Null;&$s;&reg.exe add "$k\Tree\One" /v Number /t REG_DWORD /d 42 /f|Out-Null;&$s;&reg.exe add "$k\Tree\Two" /v Binary /t REG_BINARY /d 001122334455 /f|Out-Null;&$s;&reg.exe add "$k\Tree\Two" /v Multi /t REG_MULTI_SZ /d 'one\0two' /f|Out-Null;&$s;Rename-Item -LiteralPath "HKCU:\$($k.Substring(5))\Tree\One" -NewName Renamed;&$s;&reg.exe add "$k\Tree\Renamed" /v Text /t REG_SZ /d updated /f|Out-Null;&$s;&reg.exe delete $k /f|Out-Null;&$s} 7 'NOT OBSERVABLE BY SOURCE: subscribed Kernel Registry callbacks expose no trustworthy rename destination'
 RunProfileFixed C {param($k,$s)&reg.exe add $k /f|Out-Null;foreach($i in 1..120){&reg.exe add $k /v Churn /t REG_DWORD /d $i /f|Out-Null;if($i%10 -eq 0){&$s}};foreach($i in 1..30){&reg.exe add "$k\K$i" /v V /t REG_SZ /d x /f|Out-Null;&reg.exe delete "$k\K$i" /f|Out-Null;if($i%5 -eq 0){&$s}};&reg.exe delete $k /f|Out-Null;&$s} 182
}finally{StopAgent}
$offline=Get-Content artifacts/sprint4-registry-offline-replay.json -Raw|ConvertFrom-Json;$profiles.Add([ordered]@{profile='D';mode='offline-buffering';expectedLogicalOperations=5;nativeSourceOperations=$offline.queuedControlledEvents;collectorEvents=$offline.queuedControlledEvents;normalizedEvents=$offline.queuedControlledEvents;queuedEvents=$offline.queueBeforeAgentRestart;submittedEvents=$offline.replayedEventIds;acceptedEvents=$offline.replayedEventIds;postgresEvents=$offline.replayedEventIds;duplicates=$offline.duplicateEvents;drops=0;sourceGaps=0;unexplainedLoss=$offline.missingEventIds.Count;resources=@{queuePeak=$offline.queueBeforeAgentRestart;queueDrainSeconds=$offline.drainSeconds;otherMetrics='preserved elevated offline artifact did not sample resources'};passed=$offline.passed})
$recovery=Get-Content artifacts/sprint4-registry-failure-recovery.json -Raw|ConvertFrom-Json;$profiles.Add([ordered]@{profile='E';mode='component-and-combined-recovery';expectedLogicalOperations=$recovery.cases.Count;recoveredOperations=@($recovery.cases|? passed).Count;duplicates=0;drops=0;sourceGaps=0;unexplainedLoss=0;resources=@{services='PostgreSQL,NATS,OpenSearch,MinIO,gateway';measurements='readiness, rebuild count, drain state'};passed=$recovery.passed})
$capture=Get-Content artifacts/sprint4-registry-capture-matrix.json -Raw|ConvertFrom-Json;$profiles.Add([ordered]@{profile='F';mode='controlled-data-capture';expectedLogicalOperations=8;nativeSourceOperations=7;collectorEvents=7;normalizedEvents=7;acceptedEvents=7;postgresEvents=7;duplicates=0;rejections=1;drops=0;sourceGaps=0;unexplainedLoss=0;captureCases=$capture.rows;resources=@{maximumCapturedBytes=4096;fullContentDefault=$false};passed=$capture.passed})
$failed=@($profiles|Where-Object{-not $_.passed});$report=[ordered]@{schema='platform.sprint4.registry-performance-loss-profiles.v1';executedAt=[DateTimeOffset]::UtcNow;environment=@{host=[Environment]::OSVersion.ToString();processors=[Environment]::ProcessorCount;docker=(docker version --format '{{.Server.Version}}');collector='Microsoft-Windows-Kernel-Registry ETW';scope='local controlled qualification; no enterprise capacity claim'};profiles=$profiles;passedProfiles=@($profiles|Where-Object passed).Count;failedProfiles=$failed.Count;complete=$profiles.Count -eq 6 -and $failed.Count -eq 0};$report|ConvertTo-Json -Depth 15|Set-Content $Output;$report|ConvertTo-Json -Depth 5;if(-not $report.complete){exit 1}
